package in.tucor.api.buyer; import org.springframework.data.jpa.repository.*; import jakarta.persistence.LockModeType; import java.util.*; public interface MarketListingRepository extends JpaRepository<MarketListing,UUID>{List<MarketListing> findAllByOrderByCreatedAtDesc(); Optional<MarketListing> findByPublicId(String publicId); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select l from MarketListing l where l.publicId=:publicId") Optional<MarketListing> findByPublicIdForUpdate(String publicId); long countByStatusIn(Collection<String> statuses);}